❌ Do NOT use <a href="">
✅ Use <Link /> so React doesn’t reload the page

import { Link } from "react-router-dom";

<Link
  to="/product"
  className={`text-sm font-bold tracking-tight transition-colors ${
    currentView === "product"
      ? "text-[#7edb44]"
      : "text-[#003456] hover:text-[#7edb44]"
  }`}
>
